def linear_scheduler_up_down(init_value, target_value, final_value,
                             duration_up, t_decrease, duration_down):
    """ Increases linearly to target_value, stays at target_value until
    t_decrease and then decreases linearly
    """
    if init_value < target_value:
        return init_value + (target_value - init_value) * (
            min(1, (duration_up - (t_decrease - duration_up)) / duration_up)
        )
    elif init_value > target_value:
        return init_value - (init_value - target_value) * (
            min(1, (duration_down - (t_decrease - duration_up)) / duration_down)
        )
    else:
        return target_value

